   match('الطالبة وما اكتشفته', [('ليلى', 'الشخصنة'), ('ماريا', 'المنحدر الزلق'), ('سلمى', 'المعضلة الزائفة والسبب الصحيح')]),
   order('رتّب قاعدة هند', ['الحجّة', 'الضعيفة', 'لا', 'تجعل', 'الدعوى', 'خاطئة.']),
