   order('رتّب جملة هند الأخيرة', ['الثلاث', 'السليمة', 'أضعف', 'صوتًا', 'وأقوى', 'حجّة.']),
   pic('من النصّ: «نشرت الصحيفة في صفحة الرأي مقالًا»', ['book', 'letter', 'phone'], 0),
