   cloze('أكمل السادسة', 'الارتباط ليس ___: شيئان يأتيان ___ فيُجعل أحدهما سبب الآخر، ولعلّ السبب ___.', ['سببًا', 'معًا', 'ثالث'], ['دليلًا', 'منفصلين', 'واحد']),
   cloze('أكمل حكم ماريا', 'سبب واحد ___ بدليل، وسببان ___، ولا ___، فالحكم ضعيفة.', ['صحيح', 'مغالطتان', 'تنازل'], ['طويل', 'قصيران', 'عنوان']),
   tf('يقف مقال أبي سعد مع موقف هند.', 'المقال يقف مع هند، ومع ذلك أريدكنّ أن تجدن فيه ثلاث مغالطات.', 'true', 'في صفّها.'),
