   tf('ردّ طارق على الكاتب في الصحيفة.', 'نشرت الصحيفة في صفحة الرأي مقالًا لأبي سعد عن مناظرة الأربعاء.', 'ng', 'لم يُذكر ردّ طارق.'),
   tap('المس كلمة الشخصنة', ['رجل', 'هذه', 'مصلحته', 'لا', 'تحتاج'], 'مصلحته'),
