   seq('رتّب المقال', [('man', 'الشخصنة: من مصلحته'), ('down', 'المنحدر: المعاهد فالمدارس فالصحف'), ('percent', 'السبب الصحيح: ستّون مقابل عشرين'), ('two', 'المعضلة: إمّا وإمّا')]),
