   mcq('ما المثال البديل الذي كشفت به سلمى ويوسف «من استعمله أكثر أنفق أقلّ»؟', ['التطبيق بطيء', 'المريض المزمن يطلب كثيرًا ويشتري بالجملة فينفق أقلّ على الوحدة، والتطبيق لم يفعل شيئًا', 'المستخدمون أغنياء'], 1, 'ارتباط ليس سببًا.'),
