   match('خطوة التفكيك وجملتها', [('ابدأ بما تتّفق فيه', 'السوق موجود والتطبيق سريع'), ('على الحجّة لا الشخص', 'أربع ملاحظات على الحجّة لا على سامي'), ('سمِّ واشرح', 'تعميم متسرّع فالخمسون الأوائل')]),
   order('رتّب خطوات التفكيك', ['ابدأ بما تتّفق فيه،', 'ثمّ على الحجّة لا الشخص،', 'ثمّ سمِّ واشرح بمثال بديل،', 'والشخصنة تُسمّى وتُترك.']),
   order('رتّب جملة يوسف التي كتبتها سارة', ['صفتي', 'لا', 'تُثبت', 'شيئًا', 'ولا', 'تنفيه.']),
