   pic('من النصّ: «توصيل الأدوية»', ['pharmacy', 'restaurant', 'bank'], 0),
   pic('من النصّ: «راجعت في صيدلية المستشفى ألفًا ومئتي وصفة»', ['hospital', 'school', 'hotel'], 0),
